/*
 * Configuration for building LAME's encoder library with CMake (MSVC, GCC,
 * Clang/Zig).  LAME's own config.h is generated by autotools; this replaces
 * it for the static, encoder-only build AudioCast needs.
 */

#ifndef LAME_CONFIG_H
#define LAME_CONFIG_H

#define STDC_HEADERS 1
#define HAVE_ERRNO_H 1
#define HAVE_FCNTL_H 1
#define HAVE_LIMITS_H 1
#define HAVE_STDINT_H 1
#define HAVE_INTTYPES_H 1
#define HAVE_STRCHR 1
#define HAVE_MEMCPY 1
#define PROTOTYPES 1

#define PACKAGE "lame"
#define LAME_LIBRARY_BUILD 1
#define USE_FAST_LOG 1
/* Every supported target uses IEEE 754 floats. */
#define TAKEHIRO_IEEE754_HACK 1

#include <stdint.h>

typedef float ieee754_float32_t;
typedef double ieee754_float64_t;
typedef long double ieee854_float80_t;

#endif /* LAME_CONFIG_H */
